window.VERSES = [
  {"id": "sl23-1", "livro": "sl", "ref": "Salmos 23:1", "cap": 23, "temas": ["paz", "protecao"], "texto": "O SENHOR é meu pastor, nada me faltará."},
  {"id": "sl23-4", "livro": "sl", "ref": "Salmos 23:4", "cap": 23, "temas": ["protecao", "consolo"], "texto": "Ainda que eu venha a andar pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; tua vara e teu cajado me consolam."},
  {"id": "sl27-1", "livro": "sl", "ref": "Salmos 27:1", "cap": 27, "temas": ["forca", "protecao"], "texto": "O SENHOR é minha luz e minha salvação; a quem temerei? O SENHOR é a força da minha vida; de quem terei medo?"},
  {"id": "sl34-8", "livro": "sl", "ref": "Salmos 34:8", "cap": 34, "temas": ["gratidao", "louvor"], "texto": "Experimentai, e vede que o SENHOR é bom; bem-aventurado é o homem que confia nele."},
  {"id": "sl37-5", "livro": "sl", "ref": "Salmos 37:5", "cap": 37, "temas": ["esperanca", "paz"], "texto": "Conduz teu caminho ao SENHOR, e confia nele; e ele lhe fará o bem."},
  {"id": "sl46-1", "livro": "sl", "ref": "Salmos 46:1", "cap": 46, "temas": ["protecao", "forca"], "texto": "Deus é nosso refúgio e força; socorro oportuno nas angústias."},
  {"id": "sl46-10", "livro": "sl", "ref": "Salmos 46:10", "cap": 46, "temas": ["paz"], "texto": "Ficai quietos, e sabei que eu sou Deus."},
  {"id": "sl55-22", "livro": "sl", "ref": "Salmos 55:22", "cap": 55, "temas": ["paz", "forca"], "texto": "Entrega tuas preocupações ao SENHOR, e ele te sustentará; ele não permitirá que o justo fique caído para sempre."},
  {"id": "sl56-3", "livro": "sl", "ref": "Salmos 56:3", "cap": 56, "temas": ["protecao", "forca"], "texto": "No dia em que eu tiver medo, eu confiarei em ti."},
  {"id": "sl91-1", "livro": "sl", "ref": "Salmos 91:1", "cap": 91, "temas": ["protecao", "paz"], "texto": "Aquele que mora no esconderijo do Altíssimo, à sombra do Todo-Poderoso habitará."},
  {"id": "sl91-2", "livro": "sl", "ref": "Salmos 91:2", "cap": 91, "temas": ["protecao", "forca"], "texto": "Direi ao SENHOR: Tu és meu refúgio e minha fortaleza; Deus meu, em quem confio."},
  {"id": "sl91-11", "livro": "sl", "ref": "Salmos 91:11", "cap": 91, "temas": ["protecao"], "texto": "Ele ordenou aos anjos quanto a ti, para que guardem todos os teus caminhos."},
  {"id": "sl94-19", "livro": "sl", "ref": "Salmos 94:19", "cap": 94, "temas": ["consolo", "paz"], "texto": "Quando minhas preocupações se multiplicavam dentro de mim, teus consolos confortaram a minha alma."},
  {"id": "sl100-4", "livro": "sl", "ref": "Salmos 100:4", "cap": 100, "temas": ["louvor", "gratidao"], "texto": "Entrai pelas portas dele com agradecimento, por seus pátios com canto de louvor; agradecei a ele, e bendizei o seu nome."},
  {"id": "sl103-2", "livro": "sl", "ref": "Salmos 103:2", "cap": 103, "temas": ["gratidao", "louvor"], "texto": "Louva ao SENHOR, ó minha alma; e não te esqueças de nenhum dos benefícios dele."},
  {"id": "sl118-24", "livro": "sl", "ref": "Salmos 118:24", "cap": 118, "temas": ["louvor", "gratidao"], "texto": "Este é o dia em que o SENHOR agiu; alegremos e enchamos de alegria nele."},
  {"id": "sl119-105", "livro": "sl", "ref": "Salmos 119:105", "cap": 119, "temas": ["esperanca", "forca"], "texto": "Tua palavra é lâmpada para meus pés e luz para meu caminho."},
  {"id": "sl121-1", "livro": "sl", "ref": "Salmos 121:1-2", "cap": 121, "temas": ["esperanca", "protecao"], "texto": "Levanto meus olhos aos montes. De onde virá meu socorro? Meu socorro vem do SENHOR, que fez os céus e a terra."},
  {"id": "sl121-7", "livro": "sl", "ref": "Salmos 121:7", "cap": 121, "temas": ["protecao", "paz"], "texto": "O SENHOR te guardará de todo mal; ele guardará a tua alma."},
  {"id": "sl126-5", "livro": "sl", "ref": "Salmos 126:5", "cap": 126, "temas": ["esperanca", "consolo"], "texto": "Os que semeiam em lágrimas colherão com alegria."},
  {"id": "sl139-14", "livro": "sl", "ref": "Salmos 139:14", "cap": 139, "temas": ["gratidao", "louvor"], "texto": "Eu te louvarei porque de um jeito assombroso e maravilhoso eu fui feito; maravilhosas são tuas obras; e minha alma sabe muito bem."},
  {"id": "sl30-5", "livro": "sl", "ref": "Salmos 30:5", "cap": 30, "temas": ["esperanca", "consolo"], "texto": "O choro fica pela noite, mas a alegria vem pela manhã."},
  {"id": "sl42-11", "livro": "sl", "ref": "Salmos 42:11", "cap": 42, "temas": ["esperanca", "consolo"], "texto": "Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus; porque eu ainda o louvarei."},
  {"id": "sl147-3", "livro": "sl", "ref": "Salmos 147:3", "cap": 147, "temas": ["consolo", "esperanca"], "texto": "Ele sara aos de coração partido, e os cura de suas dores."},
  {"id": "sl145-18", "livro": "sl", "ref": "Salmos 145:18", "cap": 145, "temas": ["consolo", "paz"], "texto": "O SENHOR está perto de todos os que o chamam; de todos os que clamam a ele sinceramente."},
  {"id": "sl16-8", "livro": "sl", "ref": "Salmos 16:8", "cap": 16, "temas": ["forca", "paz"], "texto": "Ponho ao SENHOR continuamente diante de mim; porque ele está à minha direita; nunca serei abalado."},
  {"id": "sl28-7", "livro": "sl", "ref": "Salmos 28:7", "cap": 28, "temas": ["forca", "gratidao"], "texto": "O SENHOR é a minha força e meu escudo; meu coração confiou nele, e foi socorrido."},
  {"id": "sl9-9", "livro": "sl", "ref": "Salmos 9:9", "cap": 9, "temas": ["protecao", "consolo"], "texto": "O SENHOR será um refúgio para o aflito; um refúgio em tempos de angústia."},
  {"id": "sl29-11", "livro": "sl", "ref": "Salmos 29:11", "cap": 29, "temas": ["paz", "forca"], "texto": "O SENHOR dará força a seu povo; o SENHOR abençoará a seu povo com paz."},
  {"id": "sl4-8", "livro": "sl", "ref": "Salmos 4:8", "cap": 4, "temas": ["paz", "protecao"], "texto": "Eu deitarei, e dormirei em paz; porque só tu, SENHOR, me fazes descansar seguro."},
  {"id": "sl73-26", "livro": "sl", "ref": "Salmos 73:26", "cap": 73, "temas": ["forca", "consolo"], "texto": "Minha carne e meu coração desfalecem; porém Deus será a rocha do meu coração e minha porção para sempre."},
  {"id": "sl86-5", "livro": "sl", "ref": "Salmos 86:5", "cap": 86, "temas": ["gratidao", "consolo"], "texto": "Tu, Senhor, és bom, perdoador, e grande em bondade para todos os que clamam a ti."},
  {"id": "sl107-1", "livro": "sl", "ref": "Salmos 107:1", "cap": 107, "temas": ["gratidao", "louvor"], "texto": "Agradecei ao SENHOR, porque ele é bom; porque sua bondade dura para sempre."},
  {"id": "sl92-1", "livro": "sl", "ref": "Salmos 92:1", "cap": 92, "temas": ["louvor", "gratidao"], "texto": "Bom é louvar ao SENHOR, e cantar louvores ao teu nome, ó Altíssimo."},
  {"id": "sl150-6", "livro": "sl", "ref": "Salmos 150:6", "cap": 150, "temas": ["louvor"], "texto": "Tudo quanto tem fôlego, louve ao SENHOR! Aleluia!"},
  {"id": "sl23-2", "livro": "sl", "ref": "Salmos 23:2", "cap": 23, "temas": ["paz"], "texto": "Ele me faz deitar em pastos verdes, e me leva a águas quietas."},
  {"id": "sl23-3", "livro": "sl", "ref": "Salmos 23:3", "cap": 23, "temas": ["paz", "forca"], "texto": "Ele restaura minha alma, e me guia pelos caminhos da justiça por seu nome."},
  {"id": "sl23-5", "livro": "sl", "ref": "Salmos 23:5", "cap": 23, "temas": ["gratidao", "protecao"], "texto": "Tu preparas uma mesa diante de mim à vista de meus adversários; unges a minha cabeça com azeite, meu cálice transborda."},
  {"id": "sl23-6", "livro": "sl", "ref": "Salmos 23:6", "cap": 23, "temas": ["esperanca", "gratidao"], "texto": "Certamente o bem e a bondade me seguirão todos os dias de minha vida; e habitarei na casa do SENHOR por muitos e muitos dias."},
  {"id": "sl91-4", "livro": "sl", "ref": "Salmos 91:4", "cap": 91, "temas": ["protecao", "paz"], "texto": "Com suas penas ele te cobrirá, e debaixo de suas asas estarás protegido; a verdade dele é escudo grande e protetor."},
  {"id": "sl91-15", "livro": "sl", "ref": "Salmos 91:15", "cap": 91, "temas": ["protecao", "consolo"], "texto": "Ele me chamará, e eu o responderei; estarei com ele na angústia; dela eu o livrarei, e o honrarei."},
  {"id": "sl19-1", "livro": "sl", "ref": "Salmos 19:1", "cap": 19, "temas": ["louvor", "gratidao"], "texto": "Os céus declaram a glória de Deus; e o firmamento anuncia a obra de suas mãos."},
  {"id": "sl19-14", "livro": "sl", "ref": "Salmos 19:14", "cap": 19, "temas": ["paz", "louvor"], "texto": "Sejam agradáveis as palavras de minha boca, e o pensamento do meu coração, diante de ti, ó SENHOR, minha rocha e meu Libertador."},
  {"id": "sl1-1", "livro": "sl", "ref": "Salmos 1:1", "cap": 1, "temas": ["paz", "sabedoria"], "texto": "Bem-aventurado o homem que não anda no conselho dos maus, nem fica parado no caminho dos pecadores, nem se senta junto dos escarnecedores."},
  {"id": "sl37-4", "livro": "sl", "ref": "Salmos 37:4", "cap": 37, "temas": ["esperanca", "gratidao"], "texto": "Agrada-te no SENHOR; e ele te dará os pedidos de teu coração."},
  {"id": "sl103-1", "livro": "sl", "ref": "Salmos 103:1", "cap": 103, "temas": ["louvor", "gratidao"], "texto": "Louva ao SENHOR, ó minha alma; e que todo o meu interior louve ao seu santo nome."},
  {"id": "sl24-1", "livro": "sl", "ref": "Salmos 24:1", "cap": 24, "temas": ["louvor", "gratidao"], "texto": "Ao SENHOR pertence a terra, e sua plenitude; o mundo, e os que nele habitam."},
  {"id": "sl51-10", "livro": "sl", "ref": "Salmos 51:10", "cap": 51, "temas": ["esperanca", "consolo"], "texto": "Cria em mim um coração puro, ó Deus; e renova um espírito firme em meu interior."},
  {"id": "sl119-11", "livro": "sl", "ref": "Salmos 119:11", "cap": 119, "temas": ["sabedoria", "forca"], "texto": "Guardei a tua palavra em meu coração, para eu não pecar contra ti."},
  {"id": "sl121-8", "livro": "sl", "ref": "Salmos 121:8", "cap": 121, "temas": ["protecao", "paz"], "texto": "O SENHOR guardará tua saída e tua entrada, desde agora e para sempre."},
  {"id": "sl34-18", "livro": "sl", "ref": "Salmos 34:18", "cap": 34, "temas": ["consolo", "esperanca"], "texto": "O SENHOR está perto daqueles que estão com o coração partido, e salva os aflitos de espírito."},
  {"id": "sl34-4", "livro": "sl", "ref": "Salmos 34:4", "cap": 34, "temas": ["protecao", "paz"], "texto": "Busquei ao SENHOR. Ele me respondeu, e me livrou de todos os meus temores."},
  {"id": "sl32-8", "livro": "sl", "ref": "Salmos 32:8", "cap": 32, "temas": ["sabedoria", "esperanca"], "texto": "Eu te instruirei, e te ensinarei o caminho que deves seguir; eu te aconselharei, e porei meus olhos em ti."},
  {"id": "sl40-1", "livro": "sl", "ref": "Salmos 40:1", "cap": 40, "temas": ["esperanca", "consolo"], "texto": "Esperei com esperança no SENHOR, e ele se inclinou a mim, e ouviu o meu clamor."},
  {"id": "sl3-3", "livro": "sl", "ref": "Salmos 3:3", "cap": 3, "temas": ["protecao", "forca"], "texto": "Porém tu, SENHOR, és escudo para mim; minha glória, e o que levanta minha cabeça."},
  {"id": "sl3-5", "livro": "sl", "ref": "Salmos 3:5", "cap": 3, "temas": ["paz", "protecao"], "texto": "Eu me deitei, e dormi; acordei, porque o SENHOR me sustentava."},
  {"id": "sl5-3", "livro": "sl", "ref": "Salmos 5:3", "cap": 5, "temas": ["esperanca", "paz"], "texto": "SENHOR, pela manhã ouvirás minha voz; pela manhã apresentarei meu clamor a ti, e ficarei esperando."},
  {"id": "sl8-1", "livro": "sl", "ref": "Salmos 8:1", "cap": 8, "temas": ["louvor"], "texto": "Ah DEUS, nosso Senhor, quão glorioso é o teu nome sobre toda a terra!"},
  {"id": "sl16-11", "livro": "sl", "ref": "Salmos 16:11", "cap": 16, "temas": ["louvor", "esperanca"], "texto": "Tu me farás conhecer o caminho da vida; fartura de alegrias há em tua presença; agrados estão em tua mão direita para sempre."},
  {"id": "sl18-2", "livro": "sl", "ref": "Salmos 18:2", "cap": 18, "temas": ["protecao", "forca"], "texto": "O SENHOR é minha rocha, e minha fortaleza, e meu libertador, meu Deus, meu rochedo, em quem confio."},
  {"id": "sl18-28", "livro": "sl", "ref": "Salmos 18:28", "cap": 18, "temas": ["esperanca", "forca"], "texto": "Tu acendes minha lâmpada; o SENHOR meu Deus ilumina as minhas trevas."},
  {"id": "sl20-4", "livro": "sl", "ref": "Salmos 20:4", "cap": 20, "temas": ["esperanca"], "texto": "Que ele dê a ti conforme o teu coração, e faça cumprir todo o teu propósito."},
  {"id": "sl25-4", "livro": "sl", "ref": "Salmos 25:4", "cap": 25, "temas": ["sabedoria", "esperanca"], "texto": "Tu me fazes conhecer os teus caminhos; ensina-me teus lugares onde se deve andar."},
  {"id": "sl27-14", "livro": "sl", "ref": "Salmos 27:14", "cap": 27, "temas": ["esperanca", "forca"], "texto": "Espera no SENHOR, esforça-te, e ele fortalecerá o teu coração; espera pois ao SENHOR."},
  {"id": "sl31-24", "livro": "sl", "ref": "Salmos 31:24", "cap": 31, "temas": ["forca", "esperanca"], "texto": "Sede fortes, e ele fortalecerá vosso coração, todos vós que esperais no SENHOR."},
  {"id": "sl32-7", "livro": "sl", "ref": "Salmos 32:7", "cap": 32, "temas": ["protecao"], "texto": "Tu és meu esconderijo, tu me guardas da angústia; tu me envolves de canções alegres de liberdade."},
  {"id": "sl34-1", "livro": "sl", "ref": "Salmos 34:1", "cap": 34, "temas": ["louvor", "gratidao"], "texto": "Louvarei ao SENHOR em todo tempo; haverá louvor a ele continuamente em minha boca."},
  {"id": "sl37-3", "livro": "sl", "ref": "Salmos 37:3", "cap": 37, "temas": ["esperanca", "sabedoria"], "texto": "Confia no SENHOR, e faze o bem; habita a terra, e te alimentarás em segurança."},
  {"id": "sl37-7", "livro": "sl", "ref": "Salmos 37:7", "cap": 37, "temas": ["paz"], "texto": "Descansa-te no SENHOR, e espera por ele."},
  {"id": "sl37-23", "livro": "sl", "ref": "Salmos 37:23", "cap": 37, "temas": ["esperanca", "sabedoria"], "texto": "Os passos do homem justo são preparados pelo SENHOR; e ele tem prazer em seu caminho."},
  {"id": "sl40-3", "livro": "sl", "ref": "Salmos 40:3", "cap": 40, "temas": ["louvor"], "texto": "Pôs em minha boca uma canção nova, um louvor para nosso Deus."},
  {"id": "sl42-1", "livro": "sl", "ref": "Salmos 42:1", "cap": 42, "temas": ["consolo", "esperanca"], "texto": "Assim como a corça geme de desejo pelas correntes de águas, assim também minha alma geme de desejo por ti, Deus."},
  {"id": "sl50-15", "livro": "sl", "ref": "Salmos 50:15", "cap": 50, "temas": ["protecao", "consolo"], "texto": "Clama a mim no dia da angústia; e eu te farei livre, e tu me glorificarás."},
  {"id": "sl57-1", "livro": "sl", "ref": "Salmos 57:1", "cap": 57, "temas": ["protecao", "consolo"], "texto": "Minha alma confia em ti, e eu me refugio sob a sombra de tuas asas, até que os meus problemas passem de mim."},
  {"id": "sl61-2", "livro": "sl", "ref": "Salmos 61:2", "cap": 61, "temas": ["consolo", "protecao"], "texto": "Desde o limite da terra eu clamo a ti, pelo sofrimento do meu coração; leva-me para uma rocha alta para mim."},
  {"id": "sl62-1", "livro": "sl", "ref": "Salmos 62:1", "cap": 62, "temas": ["paz"], "texto": "Certamente minha alma se aquieta por causa de Deus; dele vem minha salvação."},
  {"id": "sl62-8", "livro": "sl", "ref": "Salmos 62:8", "cap": 62, "temas": ["consolo", "paz"], "texto": "Confiai, povo, nele em todo o tempo; derramai vosso coração diante dele; Deus é nosso refúgio."},
  {"id": "sl63-1", "livro": "sl", "ref": "Salmos 63:1", "cap": 63, "temas": ["esperanca"], "texto": "Deus, tu és meu Deus. Eu te busco ao amanhecer; minha alma tem sede de ti."},
  {"id": "sl63-3", "livro": "sl", "ref": "Salmos 63:3", "cap": 63, "temas": ["louvor", "gratidao"], "texto": "Tua bondade é melhor que a vida; meus lábios te louvarão."},
  {"id": "sl68-19", "livro": "sl", "ref": "Salmos 68:19", "cap": 68, "temas": ["gratidao"], "texto": "Bendito seja o Senhor; dia após dia ele nos carrega; Deus é nossa salvação."},
  {"id": "sl71-5", "livro": "sl", "ref": "Salmos 71:5", "cap": 71, "temas": ["esperanca"], "texto": "Tu és minha esperança, ó Senhor DEUS; tu és minha confiança desde minha juventude."},
  {"id": "sl84-11", "livro": "sl", "ref": "Salmos 84:11", "cap": 84, "temas": ["protecao", "gratidao"], "texto": "O SENHOR Deus é sol e escudo; o SENHOR concederá graça e honra; ele não negará o bem aos que andam em integridade."},
  {"id": "sl90-12", "livro": "sl", "ref": "Salmos 90:12", "cap": 90, "temas": ["sabedoria"], "texto": "Ensina-nos a contar nossos dias de tal maneira que alcancemos um coração sábio."},
  {"id": "sl90-17", "livro": "sl", "ref": "Salmos 90:17", "cap": 90, "temas": ["forca", "esperanca"], "texto": "Que o agrado do SENHOR nosso Deus seja sobre nós; e confirma as obras de nossas mãos."},
  {"id": "sl95-1", "livro": "sl", "ref": "Salmos 95:1", "cap": 95, "temas": ["louvor"], "texto": "Vinde, cantemos alegres ao SENHOR; gritemos de alegria à rocha de nossa salvação."},
  {"id": "sl96-1", "livro": "sl", "ref": "Salmos 96:1", "cap": 96, "temas": ["louvor"], "texto": "Cantai ao SENHOR uma nova canção; cantai ao SENHOR toda a terra."},
  {"id": "sl100-5", "livro": "sl", "ref": "Salmos 100:5", "cap": 100, "temas": ["gratidao"], "texto": "O SENHOR é bom, sua bondade dura para sempre; e a fidelidade dele continua de geração após geração."},
  {"id": "sl103-12", "livro": "sl", "ref": "Salmos 103:12", "cap": 103, "temas": ["consolo"], "texto": "Assim como o oriente está longe do ocidente, assim também ele tira para longe de nós nossas transgressões."},
  {"id": "sl107-9", "livro": "sl", "ref": "Salmos 107:9", "cap": 107, "temas": ["gratidao", "consolo"], "texto": "Ele fartou a alma sedenta, e encheu de bem a alma faminta."},
  {"id": "sl111-10", "livro": "sl", "ref": "Salmos 111:10", "cap": 111, "temas": ["sabedoria"], "texto": "O temor ao SENHOR é o princípio da sabedoria; inteligentes são todos os que isto praticam."},
  {"id": "sl116-1", "livro": "sl", "ref": "Salmos 116:1", "cap": 116, "temas": ["gratidao"], "texto": "Amo o SENHOR, porque ele escuta minha voz e minhas súplicas."},
  {"id": "sl118-6", "livro": "sl", "ref": "Salmos 118:6", "cap": 118, "temas": ["protecao", "forca"], "texto": "O SENHOR está comigo, não temerei; o que poderá me fazer o homem?"},
  {"id": "sl119-50", "livro": "sl", "ref": "Salmos 119:50", "cap": 119, "temas": ["consolo"], "texto": "Isto é meu consolo na minha aflição, porque tua promessa me vivifica."},
  {"id": "sl119-114", "livro": "sl", "ref": "Salmos 119:114", "cap": 119, "temas": ["protecao", "esperanca"], "texto": "Tu és meu refúgio e meu escudo; eu espero em tua palavra."},
  {"id": "sl119-130", "livro": "sl", "ref": "Salmos 119:130", "cap": 119, "temas": ["sabedoria"], "texto": "A entrada de tuas palavras dá luz, dando entendimento aos simples."},
  {"id": "sl119-165", "livro": "sl", "ref": "Salmos 119:165", "cap": 119, "temas": ["paz"], "texto": "Muita paz têm aqueles que amam a tua lei; e para eles não há tropeço."},
  {"id": "sl121-3", "livro": "sl", "ref": "Salmos 121:3", "cap": 121, "temas": ["protecao"], "texto": "Ele não deixará o teu pé se abalar, nem cochilará o teu guardião."},
  {"id": "sl127-1", "livro": "sl", "ref": "Salmos 127:1", "cap": 127, "temas": ["sabedoria", "protecao"], "texto": "Se o SENHOR não estiver edificando a casa, em vão trabalham nela seus construtores; se o SENHOR não estiver guardando a cidade, em vão o guarda vigia."},
  {"id": "sl133-1", "livro": "sl", "ref": "Salmos 133:1", "cap": 133, "temas": ["paz"], "texto": "Vede como é bom e agradável que irmãos convivam em união!"},
  {"id": "sl136-1", "livro": "sl", "ref": "Salmos 136:1", "cap": 136, "temas": ["gratidao"], "texto": "Agradecei ao SENHOR, porque ele é bom, porque sua bondade dura para sempre."},
  {"id": "sl138-3", "livro": "sl", "ref": "Salmos 138:3", "cap": 138, "temas": ["forca"], "texto": "No dia em que clamei, tu me respondeste; e me fortaleceste com força em minha alma."},
  {"id": "sl138-8", "livro": "sl", "ref": "Salmos 138:8", "cap": 138, "temas": ["esperanca"], "texto": "O SENHOR fará por completo o que ele tem para mim; ó SENHOR, tua bondade dura para sempre."},
  {"id": "sl143-8", "livro": "sl", "ref": "Salmos 143:8", "cap": 143, "temas": ["esperanca", "sabedoria"], "texto": "De madrugada faze com que eu ouça tua bondade, porque em ti confio; faze-me saber o caminho que devo seguir, porque a ti levanto minha alma."},
  {"id": "sl143-10", "livro": "sl", "ref": "Salmos 143:10", "cap": 143, "temas": ["sabedoria"], "texto": "Ensina-me a fazer a tua vontade, pois tu és meu Deus; teu bom Espírito me guie por terra plana."},
  {"id": "sl145-8", "livro": "sl", "ref": "Salmos 145:8", "cap": 145, "temas": ["consolo"], "texto": "Piedoso e misericordioso é o SENHOR; ele demora para se irar, e tem grande bondade."},
  {"id": "sl147-5", "livro": "sl", "ref": "Salmos 147:5", "cap": 147, "temas": ["louvor"], "texto": "O nosso Senhor é grande e muito poderoso; seu entendimento é incomensurável."},
  {"id": "pv1-7", "livro": "pv", "ref": "Provérbios 1:7", "cap": 1, "temas": ["sabedoria"], "texto": "O temor ao SENHOR é o princípio do conhecimento; os tolos desprezam a sabedoria e a instrução."},
  {"id": "pv2-6", "livro": "pv", "ref": "Provérbios 2:6", "cap": 2, "temas": ["sabedoria"], "texto": "O SENHOR dá sabedoria; de sua boca vem o conhecimento e o entendimento."},
  {"id": "pv3-5", "livro": "pv", "ref": "Provérbios 3:5-6", "cap": 3, "temas": ["sabedoria", "paz"], "texto": "Confia no SENHOR com todo o teu coração; e não te apoies em teu próprio entendimento. Dá reconhecimento a ele em todos os teus caminhos; e ele endireitará tuas veredas."},
  {"id": "pv3-13", "livro": "pv", "ref": "Provérbios 3:13", "cap": 3, "temas": ["sabedoria", "gratidao"], "texto": "Bem-aventurado o homem que encontra sabedoria, e o homem que ganha conhecimento."},
  {"id": "pv3-24", "livro": "pv", "ref": "Provérbios 3:24", "cap": 3, "temas": ["paz", "protecao"], "texto": "Quando te deitares, não terás medo; tu deitarás, e teu sono será suave."},
  {"id": "pv4-18", "livro": "pv", "ref": "Provérbios 4:18", "cap": 4, "temas": ["esperanca"], "texto": "O caminho dos justos é como a luz brilhante, que vai, e ilumina até o dia ficar claro por completo."},
  {"id": "pv4-23", "livro": "pv", "ref": "Provérbios 4:23", "cap": 4, "temas": ["sabedoria"], "texto": "Acima de tudo o que se deve guardar, guarda o teu coração; porque dele procedem as saídas da vida."},
  {"id": "pv8-17", "livro": "pv", "ref": "Provérbios 8:17", "cap": 8, "temas": ["esperanca"], "texto": "Eu amo os que me amam; e os que me buscam intensamente me acharão."},
  {"id": "pv9-10", "livro": "pv", "ref": "Provérbios 9:10", "cap": 9, "temas": ["sabedoria"], "texto": "O temor ao SENHOR é o princípio da sabedoria; e o conhecimento dos santos é a prudência."},
  {"id": "pv10-12", "livro": "pv", "ref": "Provérbios 10:12", "cap": 10, "temas": ["paz"], "texto": "O ódio desperta brigas; mas o amor cobre todas as transgressões."},
  {"id": "pv10-22", "livro": "pv", "ref": "Provérbios 10:22", "cap": 10, "temas": ["gratidao"], "texto": "É a bênção do SENHOR que enriquece; e ele não lhe acrescenta dores."},
  {"id": "pv11-2", "livro": "pv", "ref": "Provérbios 11:2", "cap": 11, "temas": ["sabedoria"], "texto": "Quando vem a arrogância, vem também a desonra; mas com os humildes está a sabedoria."},
  {"id": "pv11-25", "livro": "pv", "ref": "Provérbios 11:25", "cap": 11, "temas": ["gratidao"], "texto": "A alma generosa prosperará, e aquele que saciar também será saciado."},
  {"id": "pv12-25", "livro": "pv", "ref": "Provérbios 12:25", "cap": 12, "temas": ["consolo"], "texto": "A ansiedade no coração do homem o abate; mas uma boa palavra o alegra."},
  {"id": "pv13-12", "livro": "pv", "ref": "Provérbios 13:12", "cap": 13, "temas": ["esperanca"], "texto": "A esperança que demora enfraquece o coração, mas o desejo cumprido é como uma árvore de vida."},
  {"id": "pv14-29", "livro": "pv", "ref": "Provérbios 14:29", "cap": 14, "temas": ["paz", "sabedoria"], "texto": "Quem demora para se irar tem muito entendimento, mas aquele de espírito impetuoso exalta a loucura."},
  {"id": "pv14-30", "livro": "pv", "ref": "Provérbios 14:30", "cap": 14, "temas": ["paz"], "texto": "O coração em paz é vida para o corpo, mas a inveja é como podridão nos ossos."},
  {"id": "pv15-1", "livro": "pv", "ref": "Provérbios 15:1", "cap": 15, "temas": ["paz", "sabedoria"], "texto": "A resposta suave desvia o furor, mas a palavra pesada faz a ira aumentar."},
  {"id": "pv15-13", "livro": "pv", "ref": "Provérbios 15:13", "cap": 15, "temas": ["gratidao"], "texto": "O coração alegre anima o rosto, mas pela dor do coração o espírito se abate."},
  {"id": "pv16-3", "livro": "pv", "ref": "Provérbios 16:3", "cap": 16, "temas": ["esperanca", "sabedoria"], "texto": "Confia tuas obras ao SENHOR, e teus pensamentos serão firmados."},
  {"id": "pv16-9", "livro": "pv", "ref": "Provérbios 16:9", "cap": 16, "temas": ["sabedoria", "esperanca"], "texto": "O coração do homem planeja seu caminho, mas é o SENHOR que dirige seus passos."},
  {"id": "pv16-24", "livro": "pv", "ref": "Provérbios 16:24", "cap": 16, "temas": ["consolo"], "texto": "Favo de mel são as palavras suaves: doces para a alma, e remédio para os ossos."},
  {"id": "pv16-32", "livro": "pv", "ref": "Provérbios 16:32", "cap": 16, "temas": ["forca", "paz"], "texto": "Melhor é o que demora para se irritar do que o valente; e melhor é aquele que domina seu espírito do que aquele que toma uma cidade."},
  {"id": "pv17-17", "livro": "pv", "ref": "Provérbios 17:17", "cap": 17, "temas": ["consolo"], "texto": "O amigo ama em todo tempo, e o irmão nasce para ajudar na angústia."},
  {"id": "pv17-22", "livro": "pv", "ref": "Provérbios 17:22", "cap": 17, "temas": ["gratidao", "consolo"], "texto": "O coração alegre é um bom remédio, mas o espírito abatido faz os ossos se secarem."},
  {"id": "pv18-10", "livro": "pv", "ref": "Provérbios 18:10", "cap": 18, "temas": ["protecao", "forca"], "texto": "O nome do SENHOR é uma torre forte; o justo correrá até ele, e ficará seguro."},
  {"id": "pv18-21", "livro": "pv", "ref": "Provérbios 18:21", "cap": 18, "temas": ["sabedoria"], "texto": "A morte e a vida estão no poder da língua; e aquele que a ama comerá do fruto dela."},
  {"id": "pv18-24", "livro": "pv", "ref": "Provérbios 18:24", "cap": 18, "temas": ["consolo"], "texto": "Há um amigo mais chegado que um irmão."},
  {"id": "pv19-11", "livro": "pv", "ref": "Provérbios 19:11", "cap": 19, "temas": ["paz", "sabedoria"], "texto": "A prudência do homem retém sua ira; e sua glória é ignorar a ofensa."},
  {"id": "pv19-21", "livro": "pv", "ref": "Provérbios 19:21", "cap": 19, "temas": ["sabedoria", "esperanca"], "texto": "Há muitos pensamentos no coração do homem; porém o conselho do SENHOR prevalecerá."},
  {"id": "pv22-1", "livro": "pv", "ref": "Provérbios 22:1", "cap": 22, "temas": ["sabedoria"], "texto": "É preferível ter um bom nome do que muitas riquezas; e ser favorecido é melhor que a prata e o ouro."},
  {"id": "pv22-6", "livro": "pv", "ref": "Provérbios 22:6", "cap": 22, "temas": ["sabedoria"], "texto": "Instrui ao menino em seu caminho, e até quando envelhecer, não se desviará dele."},
  {"id": "pv23-18", "livro": "pv", "ref": "Provérbios 23:18", "cap": 23, "temas": ["esperanca"], "texto": "Certamente há um bom futuro para ti, e tua expectativa não será cortada."},
  {"id": "pv24-16", "livro": "pv", "ref": "Provérbios 24:16", "cap": 24, "temas": ["forca", "esperanca"], "texto": "O justo cai sete vezes, e se levanta."},
  {"id": "pv25-11", "livro": "pv", "ref": "Provérbios 25:11", "cap": 25, "temas": ["sabedoria"], "texto": "A palavra dita em tempo apropriado é como maçãs de ouro em bandejas de prata."},
  {"id": "pv27-17", "livro": "pv", "ref": "Provérbios 27:17", "cap": 27, "temas": ["sabedoria"], "texto": "O ferro é afiado com ferro; assim também o homem afia o rosto de seu amigo."},
  {"id": "pv28-1", "livro": "pv", "ref": "Provérbios 28:1", "cap": 28, "temas": ["forca"], "texto": "Os justos são confiantes como um leão."},
  {"id": "pv29-25", "livro": "pv", "ref": "Provérbios 29:25", "cap": 29, "temas": ["protecao"], "texto": "O temor do homem arma ciladas; mas o que confia no SENHOR ficará em segurança."},
  {"id": "pv30-5", "livro": "pv", "ref": "Provérbios 30:5", "cap": 30, "temas": ["protecao"], "texto": "Toda palavra de Deus é pura; é escudo para os que nele confiam."},
  {"id": "pv31-25", "livro": "pv", "ref": "Provérbios 31:25", "cap": 31, "temas": ["forca", "esperanca"], "texto": "Força e glória são suas roupas, e ela sorri pelo seu futuro."},
  {"id": "pv31-30", "livro": "pv", "ref": "Provérbios 31:30", "cap": 31, "temas": ["sabedoria", "louvor"], "texto": "A beleza é enganosa, e a formosura é passageira; mas a mulher que teme ao SENHOR, essa será louvada."},
  {"id": "sl5-11", "livro": "sl", "ref": "Salmos 5:11", "cap": 5, "temas": ["louvor", "gratidao"], "texto": "Se alegrem todos os que confiam em ti; clamai de alegria para sempre; porque tu os proteges; e fiquem contentes em ti aqueles que amam o teu nome."},
  {"id": "sl5-12", "livro": "sl", "ref": "Salmos 5:12", "cap": 5, "temas": ["protecao", "gratidao"], "texto": "Tu, SENHOR, abençoarás ao justo; como com um escudo tu o rodearás com tua bondade."},
  {"id": "sl9-1", "livro": "sl", "ref": "Salmos 9:1", "cap": 9, "temas": ["louvor", "gratidao"], "texto": "Louvarei a ti, SENHOR com todo o meu coração; contarei todas as tuas maravilhas."},
  {"id": "sl9-10", "livro": "sl", "ref": "Salmos 9:10", "cap": 9, "temas": ["protecao", "esperanca"], "texto": "Confiarão em ti os que conhecem o teu nome; porque tu, SENHOR, nunca desamparaste aos que te buscam."},
  {"id": "sl13-5", "livro": "sl", "ref": "Salmos 13:5", "cap": 13, "temas": ["esperanca", "gratidao"], "texto": "Eu confio em tua bondade; em tua salvação meu coração se alegrará."},
  {"id": "sl16-1", "livro": "sl", "ref": "Salmos 16:1", "cap": 16, "temas": ["protecao", "paz"], "texto": "Guarda-me, ó Deus; porque eu confio em ti."},
  {"id": "sl17-8", "livro": "sl", "ref": "Salmos 17:8", "cap": 17, "temas": ["protecao"], "texto": "Guarda-me como a pupila do olho; esconde-me debaixo da sombra de tuas asas."},
  {"id": "sl18-1", "livro": "sl", "ref": "Salmos 18:1", "cap": 18, "temas": ["forca", "louvor"], "texto": "Eu te amarei, SENHOR, tu és minha força."},
  {"id": "sl18-30", "livro": "sl", "ref": "Salmos 18:30", "cap": 18, "temas": ["protecao", "sabedoria"], "texto": "O caminho de Deus é perfeito; a palavra do SENHOR é refinada; ele é escudo para todos os que nele confiam."},
  {"id": "sl18-32", "livro": "sl", "ref": "Salmos 18:32", "cap": 18, "temas": ["forca"], "texto": "Deus é o que me veste de força; e o que dá perfeição ao meu caminho."},
  {"id": "sl19-7", "livro": "sl", "ref": "Salmos 19:7", "cap": 19, "temas": ["sabedoria", "consolo"], "texto": "A lei do SENHOR é perfeita, e restaura a alma; o testemunho do SENHOR é fiel, e dá sabedoria aos simples."},
  {"id": "sl19-8", "livro": "sl", "ref": "Salmos 19:8", "cap": 19, "temas": ["sabedoria", "gratidao"], "texto": "Os preceitos do SENHOR são corretos, e alegram ao coração; o mandamento do SENHOR é puro, e ilumina aos olhos."},
  {"id": "sl25-5", "livro": "sl", "ref": "Salmos 25:5", "cap": 25, "temas": ["sabedoria", "esperanca"], "texto": "Guia-me em tua verdade, e ensina-me; porque tu és o Deus de minha salvação; eu espero por ti o dia todo."},
  {"id": "sl25-10", "livro": "sl", "ref": "Salmos 25:10", "cap": 25, "temas": ["sabedoria"], "texto": "Todos os caminhos do SENHOR são bondade e verdade, para aqueles que guardam seu pacto e seus testemunhos."},
  {"id": "sl27-4", "livro": "sl", "ref": "Salmos 27:4", "cap": 27, "temas": ["louvor"], "texto": "Pedi uma coisa ao SENHOR, e a ela buscarei: que eu possa morar na casa do SENHOR todos os dias de minha vida, para ver a beleza do SENHOR, e consultá-lo em seu Templo."},
  {"id": "sl27-5", "livro": "sl", "ref": "Salmos 27:5", "cap": 27, "temas": ["protecao"], "texto": "No dia mal ele me esconderá em seu abrigo; ele me encobrirá no oculto de sua tenda; e me porá sobre as rochas."},
  {"id": "sl27-13", "livro": "sl", "ref": "Salmos 27:13", "cap": 27, "temas": ["esperanca", "consolo"], "texto": "Se eu não tivesse crido que veria a bondade do SENHOR na terra dos viventes, certamente já teria perecido."},
  {"id": "sl29-2", "livro": "sl", "ref": "Salmos 29:2", "cap": 29, "temas": ["louvor"], "texto": "Reconhecei ao SENHOR a glória de seu nome; adorai ao SENHOR na honra da santidade."},
  {"id": "sl30-2", "livro": "sl", "ref": "Salmos 30:2", "cap": 30, "temas": ["gratidao", "consolo"], "texto": "SENHOR, meu Deus; eu clamei a ti, e tu me curaste."},
  {"id": "sl30-11", "livro": "sl", "ref": "Salmos 30:11", "cap": 30, "temas": ["consolo", "gratidao"], "texto": "Tu tornaste meu pranto em dança; tu desamarraste o meu saco de lamentação, e me envolveste de alegria."},
  {"id": "sl31-3", "livro": "sl", "ref": "Salmos 31:3", "cap": 31, "temas": ["protecao", "sabedoria"], "texto": "Tu és minha rocha e minha fortaleza; guia-me e conduz-me por causa do teu nome."},
  {"id": "sl31-14", "livro": "sl", "ref": "Salmos 31:14", "cap": 31, "temas": ["esperanca"], "texto": "Eu confio em ti, SENHOR, eu te chamo de meu Deus."},
  {"id": "sl31-19", "livro": "sl", "ref": "Salmos 31:19", "cap": 31, "temas": ["gratidao"], "texto": "Como é grande a tua bondade, que guardaste para aqueles que te temem! Tu trabalhaste para os que confiam em ti, na presença dos filhos dos homens."},
  {"id": "sl32-1", "livro": "sl", "ref": "Salmos 32:1", "cap": 32, "temas": ["consolo"], "texto": "Bem-aventurado aquele cuja transgressão é perdoada, cujo pecado é encoberto."},
  {"id": "sl33-4", "livro": "sl", "ref": "Salmos 33:4", "cap": 33, "temas": ["sabedoria"], "texto": "A palavra do SENHOR é correta; e todas suas obras são fiéis."},
  {"id": "sl33-18", "livro": "sl", "ref": "Salmos 33:18", "cap": 33, "temas": ["protecao"], "texto": "Eis que os olhos do SENHOR estão sobre aqueles que o temem, sobre os que esperam pela sua bondade."},
  {"id": "sl33-20", "livro": "sl", "ref": "Salmos 33:20", "cap": 33, "temas": ["esperanca", "protecao"], "texto": "Nossa alma espera no SENHOR; ele é nosso socorro e nosso escudo."},
  {"id": "sl33-22", "livro": "sl", "ref": "Salmos 33:22", "cap": 33, "temas": ["esperanca"], "texto": "Que tua bondade, SENHOR, esteja sobre nós, assim como nós esperamos em ti."},
  {"id": "sl34-3", "livro": "sl", "ref": "Salmos 34:3", "cap": 34, "temas": ["louvor"], "texto": "Engrandecei ao SENHOR comigo, e juntos exaltemos o seu nome."},
  {"id": "sl34-5", "livro": "sl", "ref": "Salmos 34:5", "cap": 34, "temas": ["gratidao", "esperanca"], "texto": "Os que olham para ele ficam visivelmente alegres, e seus rostos não são envergonhados."},
  {"id": "sl34-7", "livro": "sl", "ref": "Salmos 34:7", "cap": 34, "temas": ["protecao"], "texto": "O anjo do SENHOR fica ao redor daqueles que o temem, e os livra."},
  {"id": "sl34-10", "livro": "sl", "ref": "Salmos 34:10", "cap": 34, "temas": ["gratidao"], "texto": "Os filhos dos leões passam necessidades e têm fome; mas os que buscam ao SENHOR não têm falta de bem algum."},
  {"id": "sl34-17", "livro": "sl", "ref": "Salmos 34:17", "cap": 34, "temas": ["consolo", "protecao"], "texto": "Os justos clamam, e o SENHOR os ouve. Ele os livra de todas as suas angústias."},
  {"id": "sl34-19", "livro": "sl", "ref": "Salmos 34:19", "cap": 34, "temas": ["forca", "consolo"], "texto": "Muitas são as adversidades do justo, mas o SENHOR o livra de todas elas."},
  {"id": "sl36-5", "livro": "sl", "ref": "Salmos 36:5", "cap": 36, "temas": ["louvor"], "texto": "SENHOR, tua bondade alcança os céus, e tua fidelidade chega até as mais altas nuvens."},
  {"id": "sl36-7", "livro": "sl", "ref": "Salmos 36:7", "cap": 36, "temas": ["protecao", "gratidao"], "texto": "Como é preciosa, SENHOR, a tua bondade! Porque os filhos dos homens se abrigam à sombra de tuas asas."},
  {"id": "sl36-9", "livro": "sl", "ref": "Salmos 36:9", "cap": 36, "temas": ["louvor"], "texto": "Contigo está a fonte da vida; em tua luz vemos a luz verdadeira."},
  {"id": "sl37-24", "livro": "sl", "ref": "Salmos 37:24", "cap": 37, "temas": ["forca", "esperanca"], "texto": "Quando cai, ele não fica derrubado, pois o SENHOR sustenta a sua mão."},
  {"id": "sl37-39", "livro": "sl", "ref": "Salmos 37:39", "cap": 37, "temas": ["forca"], "texto": "Porém a salvação dos justos vem do SENHOR, que é a força deles no tempo de angústia."},
  {"id": "sl39-7", "livro": "sl", "ref": "Salmos 39:7", "cap": 39, "temas": ["esperanca"], "texto": "Agora, SENHOR, o que eu espero? Minha esperança está em ti."},
  {"id": "sl40-2", "livro": "sl", "ref": "Salmos 40:2", "cap": 40, "temas": ["esperanca", "forca"], "texto": "Ele me tirou de uma cova de tormento, de um lamaceiro de barro; e pôs os meus pés sobre uma rocha; ele firmou meus passos."},
  {"id": "sl40-8", "livro": "sl", "ref": "Salmos 40:8", "cap": 40, "temas": ["sabedoria"], "texto": "Meu Deus, eu desejo fazer a tua vontade; e tua Lei está no meio dos meus sentimentos."},
  {"id": "sl40-16", "livro": "sl", "ref": "Salmos 40:16", "cap": 40, "temas": ["louvor"], "texto": "Fiquem contentes e se alegrem em ti todos aqueles que te buscam; digam continuamente os que amam tua salvação: Engrandecido seja o SENHOR!"},
  {"id": "sl42-5", "livro": "sl", "ref": "Salmos 42:5", "cap": 42, "temas": ["consolo", "esperanca"], "texto": "Minha alma, por que tu estás abatida, e te inquietas em mim? Espera em Deus; pois eu o louvarei pelas suas salvações."},
  {"id": "sl42-8", "livro": "sl", "ref": "Salmos 42:8", "cap": 42, "temas": ["consolo", "paz"], "texto": "De dia o SENHOR mandará sua misericórdia, e de noite a canção dele estará comigo; uma oração ao Deus de minha vida."},
  {"id": "sl43-5", "livro": "sl", "ref": "Salmos 43:5", "cap": 43, "temas": ["consolo", "esperanca"], "texto": "Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus, porque eu ainda o louvarei; ele é a minha salvação e o meu Deus."},
  {"id": "sl46-7", "livro": "sl", "ref": "Salmos 46:7", "cap": 46, "temas": ["protecao"], "texto": "O SENHOR dos exércitos está conosco; o Deus de Jacó é nosso alto refúgio."},
  {"id": "sl47-1", "livro": "sl", "ref": "Salmos 47:1", "cap": 47, "temas": ["louvor"], "texto": "Vós todos os povos, batei palmas; clamai a Deus com voz de alegria."},
  {"id": "sl51-12", "livro": "sl", "ref": "Salmos 51:12", "cap": 51, "temas": ["consolo"], "texto": "Restaura a alegria de tua salvação, e que tu me sustentes com um espírito de boa vontade."},
  {"id": "sl51-17", "livro": "sl", "ref": "Salmos 51:17", "cap": 51, "temas": ["consolo"], "texto": "Os sacrifícios a Deus são um espírito quebrado em arrependimento; tu não desprezarás um coração quebrado e triste."},
  {"id": "sl54-4", "livro": "sl", "ref": "Salmos 54:4", "cap": 54, "temas": ["forca"], "texto": "Eis que Deus é o que me socorre; o Senhor está com aqueles que sustentam a minha alma."},
  {"id": "sl55-16", "livro": "sl", "ref": "Salmos 55:16", "cap": 55, "temas": ["protecao"], "texto": "Eu clamarei a Deus, e o SENHOR me salvará."},
  {"id": "sl55-17", "livro": "sl", "ref": "Salmos 55:17", "cap": 55, "temas": ["esperanca"], "texto": "À tarde, e pela manhã, e ao meio dia, orarei e clamarei; e ele ouvirá a minha voz."},
  {"id": "sl56-4", "livro": "sl", "ref": "Salmos 56:4", "cap": 56, "temas": ["protecao", "forca"], "texto": "Por causa de Deus eu louvarei sua palavra; confio em Deus, não temerei; o que a carne pode fazer contra mim?"},
  {"id": "sl56-8", "livro": "sl", "ref": "Salmos 56:8", "cap": 56, "temas": ["consolo"], "texto": "Tu contaste as voltas que dei por causa de meu sofrimento; põe minhas lágrimas em teu odre; não estão elas em teu livro?"},
  {"id": "sl57-7", "livro": "sl", "ref": "Salmos 57:7", "cap": 57, "temas": ["forca", "louvor"], "texto": "Firme está meu coração, ó Deus; meu coração está firme; eu cantarei, e louvarei com músicas."},
  {"id": "sl57-10", "livro": "sl", "ref": "Salmos 57:10", "cap": 57, "temas": ["louvor"], "texto": "Tua bondade é grande, alcança até os céus; e a tua fidelidade até as nuvens mais altas."},
  {"id": "sl59-16", "livro": "sl", "ref": "Salmos 59:16", "cap": 59, "temas": ["louvor", "protecao"], "texto": "Eu cantarei sobre tua força; e pela manhã com alegria louvarei tua bondade; porque tu tens sido meu alto refúgio e abrigo no dia da minha angústia."},
  {"id": "sl59-17", "livro": "sl", "ref": "Salmos 59:17", "cap": 59, "temas": ["forca", "louvor"], "texto": "Cantarei louvores a ti, que és minha força; porque Deus é o meu refúgio, ó Deus de bondade para comigo."},
  {"id": "sl61-1", "livro": "sl", "ref": "Salmos 61:1", "cap": 61, "temas": ["consolo"], "texto": "Ouve, ó Deus, o meu clamor; presta atenção à minha oração."},
  {"id": "sl61-3", "livro": "sl", "ref": "Salmos 61:3", "cap": 61, "temas": ["protecao"], "texto": "Tu tens sido o meu refúgio e torre forte perante o inimigo."},
  {"id": "sl62-2", "livro": "sl", "ref": "Salmos 62:2", "cap": 62, "temas": ["protecao", "paz"], "texto": "Certamente ele é minha rocha, minha salvação e meu refúgio; não serei muito abalado."},
  {"id": "sl62-5", "livro": "sl", "ref": "Salmos 62:5", "cap": 62, "temas": ["paz", "esperanca"], "texto": "Tu, porém, ó minha alma, aquieta-te em Deus; porque ele é minha esperança."},
  {"id": "sl63-7", "livro": "sl", "ref": "Salmos 63:7", "cap": 63, "temas": ["gratidao", "protecao"], "texto": "Tu tens sido meu socorro; e à sombra de tuas asas cantarei de alegria."},
  {"id": "sl63-8", "livro": "sl", "ref": "Salmos 63:8", "cap": 63, "temas": ["forca", "consolo"], "texto": "Minha alma está apegada a ti; tua mão direita me sustenta."},
  {"id": "sl66-20", "livro": "sl", "ref": "Salmos 66:20", "cap": 66, "temas": ["gratidao"], "texto": "Bendito seja Deus, que não ignorou minha oração, nem sua bondade se desviou de mim."},
  {"id": "sl67-1", "livro": "sl", "ref": "Salmos 67:1", "cap": 67, "temas": ["gratidao"], "texto": "Que Deus tenha misericórdia de nós, e nos abençoe; que ele brilhe seu rosto sobre nós."},
  {"id": "sl68-5", "livro": "sl", "ref": "Salmos 68:5", "cap": 68, "temas": ["consolo"], "texto": "Ele é o pai dos órfãos, e juiz que defende as viúvas; Deus na habitação de sua santidade."},
  {"id": "sl69-30", "livro": "sl", "ref": "Salmos 69:30", "cap": 69, "temas": ["louvor", "gratidao"], "texto": "Louvarei o nome de Deus com cântico; e o engrandecerei com agradecimentos."},
  {"id": "sl71-3", "livro": "sl", "ref": "Salmos 71:3", "cap": 71, "temas": ["protecao"], "texto": "Sê tu minha rocha e minha habitação, para continuamente eu me abrigar nela; tu tens ordenado que eu seja salvo, porque tu és minha rocha forte e minha fortaleza."},
  {"id": "sl71-14", "livro": "sl", "ref": "Salmos 71:14", "cap": 71, "temas": ["esperanca"], "texto": "Porém eu continuamente manterei a esperança, e darei todo o louvor a ti ainda mais."},
  {"id": "sl73-23", "livro": "sl", "ref": "Salmos 73:23", "cap": 73, "temas": ["consolo"], "texto": "Porém agora estarei continuamente contigo; tu tens segurado minha mão direita."},
  {"id": "sl73-24", "livro": "sl", "ref": "Salmos 73:24", "cap": 73, "temas": ["sabedoria"], "texto": "Tu me guiarás com teu conselho, e depois me receberás em glória."},
  {"id": "sl73-25", "livro": "sl", "ref": "Salmos 73:25", "cap": 73, "temas": ["paz"], "texto": "A quem tenho no céu além de ti? E quando estou contigo, nada há na terra que eu deseje."},
  {"id": "sl73-28", "livro": "sl", "ref": "Salmos 73:28", "cap": 73, "temas": ["esperanca"], "texto": "Quanto a mim, bom me é me aproximar de Deus; ponho minha confiança no Senhor DEUS, para que eu conte todas as tuas obras."},
  {"id": "sl84-1", "livro": "sl", "ref": "Salmos 84:1", "cap": 84, "temas": ["louvor"], "texto": "Quão agradáveis são tuas moradas, SENHOR dos exércitos!"},
  {"id": "sl84-5", "livro": "sl", "ref": "Salmos 84:5", "cap": 84, "temas": ["forca"], "texto": "Bem-aventurados aqueles cuja força está em ti, em cujos corações estão os caminhos corretos."},
  {"id": "sl84-10", "livro": "sl", "ref": "Salmos 84:10", "cap": 84, "temas": ["louvor"], "texto": "Melhor é um dia nos teus pátios, do que mil fora."},
  {"id": "sl85-8", "livro": "sl", "ref": "Salmos 85:8", "cap": 85, "temas": ["paz"], "texto": "Escutarei o que o Deus, o SENHOR, falar, pois ele falará de paz ao seu povo."},
  {"id": "sl85-10", "livro": "sl", "ref": "Salmos 85:10", "cap": 85, "temas": ["paz"], "texto": "A bondade e a verdade se encontrarão; a justiça e a paz se beijarão."},
  {"id": "sl86-7", "livro": "sl", "ref": "Salmos 86:7", "cap": 86, "temas": ["consolo"], "texto": "No dia de minha angústia clamarei a ti, pois tu me responderás."},
  {"id": "sl86-11", "livro": "sl", "ref": "Salmos 86:11", "cap": 86, "temas": ["sabedoria"], "texto": "Ensina-me, SENHOR, o teu caminho, e eu andarei em tua verdade; une meu coração com o temor ao teu nome."},
  {"id": "sl86-12", "livro": "sl", "ref": "Salmos 86:12", "cap": 86, "temas": ["louvor"], "texto": "Louvarei a ti, ó Senhor meu Deus, com todo o meu coração; e glorificarei o teu nome para sempre."},
  {"id": "sl89-1", "livro": "sl", "ref": "Salmos 89:1", "cap": 89, "temas": ["louvor"], "texto": "Cantarei das bondades do SENHOR para sempre; de geração em geração com minha boca anunciarei tua fidelidade."},
  {"id": "sl89-15", "livro": "sl", "ref": "Salmos 89:15", "cap": 89, "temas": ["louvor"], "texto": "Bem-aventurado é o povo que entende o grito de alegria; ó SENHOR, eles andarão na luz de tua face."},
  {"id": "sl90-1", "livro": "sl", "ref": "Salmos 90:1", "cap": 90, "temas": ["protecao"], "texto": "Senhor, tu tens sido nossa habitação, de geração em geração."},
  {"id": "sl90-2", "livro": "sl", "ref": "Salmos 90:2", "cap": 90, "temas": ["louvor"], "texto": "Antes que os montes surgissem, e tu produzisses a terra e o mundo, desde à eternidade até a eternidade tu és Deus."},
  {"id": "sl90-14", "livro": "sl", "ref": "Salmos 90:14", "cap": 90, "temas": ["gratidao"], "texto": "Farta-nos de manhã com tua bondade; e nos alegraremos e seremos cheios de alegria por todos os nossos dias."},
  {"id": "sl91-5", "livro": "sl", "ref": "Salmos 91:5", "cap": 91, "temas": ["protecao", "paz"], "texto": "Não terás medo do terror da noite, nem da flecha que voa de dia."},
  {"id": "sl91-9", "livro": "sl", "ref": "Salmos 91:9", "cap": 91, "temas": ["protecao"], "texto": "Tu fizeste como morada ao SENHOR: o meu refúgio, o Altíssimo."},
  {"id": "sl91-14", "livro": "sl", "ref": "Salmos 91:14", "cap": 91, "temas": ["protecao"], "texto": "Por ele ter me amado tanto, eu também o livrarei; em alto retiro eu o porei, porque ele conhece o meu nome."},
  {"id": "sl92-4", "livro": "sl", "ref": "Salmos 92:4", "cap": 92, "temas": ["gratidao"], "texto": "Tu, SENHOR, tens me alegrado com teus feitos; cantarei de alegria pelas obras de tuas mãos."},
  {"id": "sl92-12", "livro": "sl", "ref": "Salmos 92:12", "cap": 92, "temas": ["esperanca"], "texto": "O justo florescerá como a palma; crescerá como o cedro do Líbano."},
  {"id": "sl94-18", "livro": "sl", "ref": "Salmos 94:18", "cap": 94, "temas": ["forca", "consolo"], "texto": "Quando eu dizia: Meu pé está escorregando; Tua bondade, ó SENHOR, me sustentava."},
  {"id": "sl94-22", "livro": "sl", "ref": "Salmos 94:22", "cap": 94, "temas": ["protecao"], "texto": "O SENHOR é meu alto retiro, e meu Deus a rocha de meu refúgio."},
  {"id": "sl95-6", "livro": "sl", "ref": "Salmos 95:6", "cap": 95, "temas": ["louvor"], "texto": "Vinde, adoremos, e prostremo-nos; ajoelhemo-nos perante o SENHOR, que nos fez."},
  {"id": "sl97-11", "livro": "sl", "ref": "Salmos 97:11", "cap": 97, "temas": ["esperanca"], "texto": "A luz é semeada para o justo, e a alegria para os corretos de coração."},
  {"id": "sl98-1", "livro": "sl", "ref": "Salmos 98:1", "cap": 98, "temas": ["louvor"], "texto": "Cantai ao SENHOR uma canção nova, porque ele fez maravilhas."},
  {"id": "sl100-1", "livro": "sl", "ref": "Salmos 100:1", "cap": 100, "temas": ["louvor"], "texto": "Gritai de alegria ao SENHOR toda a terra!"},
  {"id": "sl100-3", "livro": "sl", "ref": "Salmos 100:3", "cap": 100, "temas": ["gratidao"], "texto": "Sabei que o SENHOR é Deus; foi ele, e não nós, que nos fez seu povo, e ovelhas de seu pasto."},
  {"id": "sl103-8", "livro": "sl", "ref": "Salmos 103:8", "cap": 103, "temas": ["consolo"], "texto": "Misericordioso e piedoso é o SENHOR, que demora para se irar, e é grande em bondade."},
  {"id": "sl103-11", "livro": "sl", "ref": "Salmos 103:11", "cap": 103, "temas": ["gratidao"], "texto": "Porque, assim como os céus estão bem mais elevados que a terra, assim também prevalece a bondade dele sobre aqueles que o temem."},
  {"id": "sl103-13", "livro": "sl", "ref": "Salmos 103:13", "cap": 103, "temas": ["consolo"], "texto": "Assim como um pai se compadece dos filhos, assim também o SENHOR se compadece daqueles que o temem."},
  {"id": "sl104-24", "livro": "sl", "ref": "Salmos 104:24", "cap": 104, "temas": ["louvor"], "texto": "Como são muitas as suas obras, SENHOR! Tu fizeste todas com sabedoria; a terra está cheia de teus bens."},
  {"id": "sl104-33", "livro": "sl", "ref": "Salmos 104:33", "cap": 104, "temas": ["louvor"], "texto": "Cantarei ao SENHOR em toda a minha vida; tocarei música ao meu Deus enquanto eu existir."},
  {"id": "sl105-4", "livro": "sl", "ref": "Salmos 105:4", "cap": 105, "temas": ["forca"], "texto": "Buscai ao SENHOR e à sua força; buscai a presença dele continuamente."},
  {"id": "sl106-1", "livro": "sl", "ref": "Salmos 106:1", "cap": 106, "temas": ["gratidao"], "texto": "Aleluia! Agradecei ao SENHOR, porque ele é bom, porque sua bondade dura para sempre."},
  {"id": "sl107-29", "livro": "sl", "ref": "Salmos 107:29", "cap": 107, "temas": ["paz"], "texto": "Ele fez cessar as tormentas, e as ondas se calaram."},
  {"id": "sl112-1", "livro": "sl", "ref": "Salmos 112:1", "cap": 112, "temas": ["sabedoria"], "texto": "Aleluia! Bem-aventurado é o homem que teme ao SENHOR, e que tem muito prazer em seus mandamentos."},
  {"id": "sl112-7", "livro": "sl", "ref": "Salmos 112:7", "cap": 112, "temas": ["paz"], "texto": "Ele não temerá o mau rumor; o seu coração está firme, confiante no SENHOR."},
  {"id": "sl113-3", "livro": "sl", "ref": "Salmos 113:3", "cap": 113, "temas": ["louvor"], "texto": "Desde o nascer do sol até o poente, seja louvado o nome do SENHOR."},
  {"id": "sl115-1", "livro": "sl", "ref": "Salmos 115:1", "cap": 115, "temas": ["louvor"], "texto": "Não a nós, SENHOR; não a nós, mas a teu nome dá glória; por tua bondade, por tua fidelidade."},
  {"id": "sl116-7", "livro": "sl", "ref": "Salmos 116:7", "cap": 116, "temas": ["paz"], "texto": "Minha alma, volta ao teu descanso, pois o SENHOR tem te tratado bem."},
  {"id": "sl117-2", "livro": "sl", "ref": "Salmos 117:2", "cap": 117, "temas": ["gratidao"], "texto": "Sua bondade prevaleceu sobre nós, e a fidelidade do SENHOR dura para sempre. Aleluia!"},
  {"id": "sl118-1", "livro": "sl", "ref": "Salmos 118:1", "cap": 118, "temas": ["gratidao"], "texto": "Agradecei ao SENHOR, porque ele é bom; pois sua bondade dura para sempre."},
  {"id": "sl118-5", "livro": "sl", "ref": "Salmos 118:5", "cap": 118, "temas": ["consolo"], "texto": "Na angústia clamei ao SENHOR; e o SENHOR me respondeu, e me pôs num lugar amplo."},
  {"id": "sl118-8", "livro": "sl", "ref": "Salmos 118:8", "cap": 118, "temas": ["protecao"], "texto": "Melhor é buscar refúgio no SENHOR do que confiar no homem."},
  {"id": "sl118-14", "livro": "sl", "ref": "Salmos 118:14", "cap": 118, "temas": ["forca"], "texto": "O SENHOR é minha força e minha canção, porque ele tem sido minha salvação."},
  {"id": "sl119-18", "livro": "sl", "ref": "Salmos 119:18", "cap": 119, "temas": ["sabedoria"], "texto": "Abre meus olhos, para que eu veja as maravilhas de tua lei."},
  {"id": "sl119-28", "livro": "sl", "ref": "Salmos 119:28", "cap": 119, "temas": ["consolo"], "texto": "Minha alma se derrama de tristeza; levanta-me conforme tua palavra."},
  {"id": "sl119-68", "livro": "sl", "ref": "Salmos 119:68", "cap": 119, "temas": ["sabedoria"], "texto": "Tu és bom, e fazes o bem; ensina-me os teus estatutos."},
  {"id": "sl119-71", "livro": "sl", "ref": "Salmos 119:71", "cap": 119, "temas": ["sabedoria"], "texto": "Foi bom pra mim ter sido afligido, para assim eu aprender os teus estatutos."},
  {"id": "sl119-76", "livro": "sl", "ref": "Salmos 119:76", "cap": 119, "temas": ["consolo"], "texto": "Seja agora tua bondade para me consolar, segundo a promessa que fizeste a teu servo."},
  {"id": "sl119-89", "livro": "sl", "ref": "Salmos 119:89", "cap": 119, "temas": ["esperanca"], "texto": "Para sempre, SENHOR, tua palavra permanece nos céus."},
  {"id": "sl119-97", "livro": "sl", "ref": "Salmos 119:97", "cap": 119, "temas": ["sabedoria"], "texto": "Ah, como eu amo a tua lei! O dia todo eu medito nela."},
  {"id": "sl119-103", "livro": "sl", "ref": "Salmos 119:103", "cap": 119, "temas": ["gratidao"], "texto": "Como são doces tuas palavras ao meu paladar! Mais que o mel em minha boca."},
  {"id": "sl121-5", "livro": "sl", "ref": "Salmos 121:5", "cap": 121, "temas": ["protecao"], "texto": "O SENHOR é o teu guardião; o SENHOR é a sombra à tua direita."},
  {"id": "sl124-8", "livro": "sl", "ref": "Salmos 124:8", "cap": 124, "temas": ["protecao"], "texto": "Nosso socorro está no nome do SENHOR, que fez o céu e a terra."},
  {"id": "sl125-1", "livro": "sl", "ref": "Salmos 125:1", "cap": 125, "temas": ["forca"], "texto": "Os que confiam no SENHOR são como o monte de Sião, que não se abala, e permanece para sempre."},
  {"id": "sl125-2", "livro": "sl", "ref": "Salmos 125:2", "cap": 125, "temas": ["protecao"], "texto": "Assim como montanhas estão ao redor de Jerusalém, assim também o SENHOR está ao redor de seu povo, desde agora para sempre."},
  {"id": "sl126-3", "livro": "sl", "ref": "Salmos 126:3", "cap": 126, "temas": ["gratidao"], "texto": "Grandes coisas o SENHOR fez para nós; por isso estamos alegres."},
  {"id": "sl127-2", "livro": "sl", "ref": "Salmos 127:2", "cap": 127, "temas": ["paz"], "texto": "Assim ele dá sono a quem ele ama."},
  {"id": "sl130-5", "livro": "sl", "ref": "Salmos 130:5", "cap": 130, "temas": ["esperanca"], "texto": "Mantenho esperança no SENHOR, a minha alma espera; e persisto em sua palavra."},
  {"id": "sl138-7", "livro": "sl", "ref": "Salmos 138:7", "cap": 138, "temas": ["forca"], "texto": "Enquanto ando no meio da angústia, tu me vivificas."},
  {"id": "sl139-1", "livro": "sl", "ref": "Salmos 139:1", "cap": 139, "temas": ["consolo"], "texto": "SENHOR, tu me examinas e me conheces."},
  {"id": "sl139-9", "livro": "sl", "ref": "Salmos 139:9-10", "cap": 139, "temas": ["protecao"], "texto": "Se eu tomasse as asas do amanhecer, e morasse nos limites do mar, até ali tua mão me guiaria, e tua mão direita me seguraria."},
  {"id": "sl139-23", "livro": "sl", "ref": "Salmos 139:23", "cap": 139, "temas": ["sabedoria"], "texto": "Examina-me, Deus, e conhece meu coração; prova-me, e conhece meus pensamentos."},
  {"id": "sl141-3", "livro": "sl", "ref": "Salmos 141:3", "cap": 141, "temas": ["sabedoria"], "texto": "Põe, SENHOR, uma guarda em minha boca; vigia a abertura dos meus lábios."},
  {"id": "sl143-1", "livro": "sl", "ref": "Salmos 143:1", "cap": 143, "temas": ["consolo"], "texto": "Ó SENHOR, ouve minha oração; inclina teus ouvidos às minhas súplicas; responde-me segundo tua fidelidade e tua justiça."},
  {"id": "sl145-3", "livro": "sl", "ref": "Salmos 145:3", "cap": 145, "temas": ["louvor"], "texto": "O SENHOR é grande e muito louvável; sua grandeza é incompreensível."},
  {"id": "sl145-9", "livro": "sl", "ref": "Salmos 145:9", "cap": 145, "temas": ["gratidao"], "texto": "O SENHOR é bom para com todos; e suas misericórdias estão sobre todas as obras que ele fez."},
  {"id": "sl145-14", "livro": "sl", "ref": "Salmos 145:14", "cap": 145, "temas": ["consolo"], "texto": "O SENHOR segura todos os que caem, e levanta todos os abatidos."},
  {"id": "sl146-5", "livro": "sl", "ref": "Salmos 146:5", "cap": 146, "temas": ["esperanca"], "texto": "Bem-aventurado aquele que tem o Deus de Jacó como sua ajuda, cuja esperança está no SENHOR seu Deus."},
  {"id": "sl146-8", "livro": "sl", "ref": "Salmos 146:8", "cap": 146, "temas": ["consolo"], "texto": "O SENHOR abre os olhos dos cegos; o SENHOR levanta aos abatidos; o SENHOR ama aos justos."},
  {"id": "sl147-11", "livro": "sl", "ref": "Salmos 147:11", "cap": 147, "temas": ["esperanca"], "texto": "O SENHOR se agrada dos que o temem, daqueles que esperam por sua bondade."},
  {"id": "sl149-4", "livro": "sl", "ref": "Salmos 149:4", "cap": 149, "temas": ["gratidao"], "texto": "O SENHOR se agrada de seu povo; ele ornará os mansos com salvação."},
  {"id": "pv3-3", "livro": "pv", "ref": "Provérbios 3:3", "cap": 3, "temas": ["sabedoria"], "texto": "Que a bondade e a fidelidade não te desamparem; amarra-as junto ao teu pescoço; escreve-as na tábua de teu coração."},
  {"id": "pv3-7", "livro": "pv", "ref": "Provérbios 3:7", "cap": 3, "temas": ["sabedoria"], "texto": "Não sejas sábio aos teus próprios olhos; teme ao SENHOR, e afasta-te do mal."},
  {"id": "pv3-26", "livro": "pv", "ref": "Provérbios 3:26", "cap": 3, "temas": ["protecao"], "texto": "O SENHOR será tua esperança; e ele guardará teus pés para que não sejam presos."},
  {"id": "pv3-27", "livro": "pv", "ref": "Provérbios 3:27", "cap": 3, "temas": ["sabedoria"], "texto": "Não detenhas o bem daqueles que possuem o direito, se tiveres em tuas mãos poder para o fazeres."},
  {"id": "pv4-7", "livro": "pv", "ref": "Provérbios 4:7", "cap": 4, "temas": ["sabedoria"], "texto": "O principal é a sabedoria; adquire sabedoria, e acima de tudo o que adquirires, adquire entendimento."},
  {"id": "pv4-26", "livro": "pv", "ref": "Provérbios 4:26", "cap": 4, "temas": ["sabedoria"], "texto": "Pondera o curso de teus pés; e todos os teus caminhos sejam bem ordenados."},
  {"id": "pv8-11", "livro": "pv", "ref": "Provérbios 8:11", "cap": 8, "temas": ["sabedoria"], "texto": "A sabedoria é melhor do que rubis; e todas as coisas desejáveis nem sequer podem ser comparadas a ela."},
  {"id": "pv10-9", "livro": "pv", "ref": "Provérbios 10:9", "cap": 10, "temas": ["sabedoria"], "texto": "Aquele que anda em sinceridade anda seguro; mas o que perverte seus caminhos será conhecido."},
  {"id": "pv10-19", "livro": "pv", "ref": "Provérbios 10:19", "cap": 10, "temas": ["sabedoria", "paz"], "texto": "Na abundância de palavras não há falta de transgressão; mas aquele que refreia seus lábios é prudente."},
  {"id": "pv11-14", "livro": "pv", "ref": "Provérbios 11:14", "cap": 11, "temas": ["sabedoria"], "texto": "Quando não há conselhos sábios, o povo cai; mas na abundância de bons conselheiros consiste o livramento."},
  {"id": "pv11-17", "livro": "pv", "ref": "Provérbios 11:17", "cap": 11, "temas": ["sabedoria"], "texto": "O homem bondoso faz bem à sua alma; mas o cruel atormenta sua própria carne."},
  {"id": "pv12-18", "livro": "pv", "ref": "Provérbios 12:18", "cap": 12, "temas": ["sabedoria"], "texto": "Há alguns que falam palavras como que golpes de espada; porém a língua dos sábios é como um remédio."},
  {"id": "pv13-20", "livro": "pv", "ref": "Provérbios 13:20", "cap": 13, "temas": ["sabedoria"], "texto": "Quem anda com os sábios se torna sábio; mas aquele que acompanha os tolos sofrerá."},
  {"id": "pv15-15", "livro": "pv", "ref": "Provérbios 15:15", "cap": 15, "temas": ["gratidao"], "texto": "Todos os dias do oprimido são maus, mas o coração alegre é como um banquete contínuo."},
  {"id": "pv15-16", "livro": "pv", "ref": "Provérbios 15:16", "cap": 15, "temas": ["paz"], "texto": "Melhor é o pouco tendo o temor ao SENHOR, do que um grande tesouro tendo em si inquietação."},
  {"id": "pv15-22", "livro": "pv", "ref": "Provérbios 15:22", "cap": 15, "temas": ["sabedoria"], "texto": "Os planos fracassam quando não há bom conselho; mas com abundância de conselheiros eles se confirmam."},
  {"id": "pv15-23", "livro": "pv", "ref": "Provérbios 15:23", "cap": 15, "temas": ["sabedoria"], "texto": "O homem se alegra com a resposta de sua boca; e como é boa a palavra a seu devido tempo!"},
  {"id": "pv15-30", "livro": "pv", "ref": "Provérbios 15:30", "cap": 15, "temas": ["gratidao"], "texto": "A luz dos olhos alegra o coração; a boa notícia fortalece os ossos."},
  {"id": "pv16-7", "livro": "pv", "ref": "Provérbios 16:7", "cap": 16, "temas": ["paz"], "texto": "Quando os caminhos do homem são agradáveis ao SENHOR, ele faz até seus inimigos terem paz com ele."},
  {"id": "pv16-16", "livro": "pv", "ref": "Provérbios 16:16", "cap": 16, "temas": ["sabedoria"], "texto": "Obter sabedoria é tão melhor do que o ouro! E obter sabedoria é mais excelente do que a prata."},
  {"id": "pv16-20", "livro": "pv", "ref": "Provérbios 16:20", "cap": 16, "temas": ["sabedoria"], "texto": "Aquele que pensa prudentemente na palavra encontrará o bem; e quem confia no SENHOR é bem-aventurado."},
  {"id": "pv17-9", "livro": "pv", "ref": "Provérbios 17:9", "cap": 17, "temas": ["paz"], "texto": "Quem perdoa a transgressão busca a amizade; mas quem repete o assunto afasta amigos íntimos."},
  {"id": "pv17-27", "livro": "pv", "ref": "Provérbios 17:27", "cap": 17, "temas": ["paz", "sabedoria"], "texto": "Quem entende o conhecimento guarda suas palavras; e o homem de bom entendimento é de espírito calmo."},
  {"id": "pv18-15", "livro": "pv", "ref": "Provérbios 18:15", "cap": 18, "temas": ["sabedoria"], "texto": "O coração do prudente adquire conhecimento; e o ouvido dos sábios busca conhecimento."},
  {"id": "pv19-17", "livro": "pv", "ref": "Provérbios 19:17", "cap": 19, "temas": ["gratidao"], "texto": "Quem faz misericórdia ao pobre empresta ao SENHOR; e ele lhe pagará sua recompensa."},
  {"id": "pv19-20", "livro": "pv", "ref": "Provérbios 19:20", "cap": 19, "temas": ["sabedoria"], "texto": "Ouve o conselho, e recebe a disciplina; para que sejas sábio nos teus últimos dias."},
  {"id": "pv20-22", "livro": "pv", "ref": "Provérbios 20:22", "cap": 20, "temas": ["paz"], "texto": "Não digas: Devolverei o mal; Espera pelo SENHOR, e ele te livrará."},
  {"id": "pv21-21", "livro": "pv", "ref": "Provérbios 21:21", "cap": 21, "temas": ["sabedoria"], "texto": "Quem segue a justiça e a bondade achará vida, justiça e honra."},
  {"id": "pv21-23", "livro": "pv", "ref": "Provérbios 21:23", "cap": 21, "temas": ["sabedoria"], "texto": "Quem guarda sua boca e sua língua guarda sua alma de angústias."},
  {"id": "pv22-4", "livro": "pv", "ref": "Provérbios 22:4", "cap": 22, "temas": ["sabedoria"], "texto": "A recompensa da humildade e do temor ao SENHOR são riquezas, honra, e vida."},
  {"id": "pv22-9", "livro": "pv", "ref": "Provérbios 22:9", "cap": 22, "temas": ["gratidao"], "texto": "Quem tem olhos bondosos será abençoado, porque deu de seu pão ao pobre."},
  {"id": "pv27-1", "livro": "pv", "ref": "Provérbios 27:1", "cap": 27, "temas": ["sabedoria"], "texto": "Não te orgulhes do dia de amanhã; porque não sabes o que o dia trará."},
  {"id": "pv27-2", "livro": "pv", "ref": "Provérbios 27:2", "cap": 27, "temas": ["sabedoria"], "texto": "Que o estranho te louve, e não tua própria boca; o estrangeiro, e não teus próprios lábios."},
  {"id": "pv27-9", "livro": "pv", "ref": "Provérbios 27:9", "cap": 27, "temas": ["consolo"], "texto": "O óleo e o perfume alegram ao coração; assim é a doçura de um amigo com um conselho sincero."},
  {"id": "pv28-13", "livro": "pv", "ref": "Provérbios 28:13", "cap": 28, "temas": ["consolo"], "texto": "Quem encobre suas transgressões nunca prosperará, mas aquele que as confessa e as abandona alcançará misericórdia."},
  {"id": "pv29-11", "livro": "pv", "ref": "Provérbios 29:11", "cap": 29, "temas": ["paz"], "texto": "O louco mostra todo o seu ímpeto; mas o sábio o mantém sob controle."},
  {"id": "pv31-10", "livro": "pv", "ref": "Provérbios 31:10", "cap": 31, "temas": ["louvor"], "texto": "Mulher virtuosa, quem a encontrará? Pois seu valor é muito maior que o de rubis."},
  {"id": "pv31-26", "livro": "pv", "ref": "Provérbios 31:26", "cap": 31, "temas": ["sabedoria"], "texto": "Ela abre sua boca com sabedoria; e o ensinamento bondoso está em sua língua."}
];

